-- =============================================================================
-- V1 — Extensions, identity, session & shared security tables
-- Owner : Lê Bá Tiệp (identity, profile, shared)
-- Tables: users, refresh_tokens, idempotency_keys, admin_audit_logs
-- Source: docs/Hanoi_Lens_Database.md (PostgreSQL 16 + PostGIS + pgvector)
--
-- Conventions for every migration (V1..V5):
--   * Primary keys are UUID, generated by the application (UUIDv7) — no DB default.
--   * All timestamps are TIMESTAMPTZ (UTC); localise only at the presentation layer.
--   * Enumerations are VARCHAR + CHECK (not PG ENUM) so values can change in a
--     later migration without ALTER TYPE.
--   * Foreign keys: composition children CASCADE; optional references SET NULL;
--     everything else RESTRICT (default).
--   * PostgreSQL does not index FK columns automatically; indexes are explicit.
-- A merged migration is never edited — add a new V6__... instead.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS postgis;   -- geofence boundaries (SRID 4326)
CREATE EXTENSION IF NOT EXISTS vector;    -- pgvector, RAG embeddings

CREATE TABLE users (
    id                       UUID         NOT NULL,
    email                    VARCHAR(254) NOT NULL,
    password_hash            VARCHAR(255) NOT NULL,
    display_name             VARCHAR(120) NOT NULL,
    role                     VARCHAR(16)  NOT NULL DEFAULT 'USER',
    status                   VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    locale                   VARCHAR(16)  NOT NULL DEFAULT 'vi',
    default_location_display VARCHAR(16)  NOT NULL,
    created_at               TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT ck_users_role   CHECK (role IN ('USER', 'ADMIN')),
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'DISABLED')),
    CONSTRAINT ck_users_default_location_display
        CHECK (default_location_display IN ('EXACT', 'DISTRICT', 'HIDDEN'))
);

-- Case-insensitive unique email (no citext dependency).
CREATE UNIQUE INDEX uq_users_email_lower ON users (lower(email));

COMMENT ON TABLE  users IS 'Account + profile + default location-privacy policy (profile fields live here, per the 21-table model).';
COMMENT ON COLUMN users.password_hash IS 'Argon2id (bcrypt cost >= 12 fallback). Never returned in DTOs or logged (SECURITY §5).';
COMMENT ON COLUMN users.role IS 'USER | ADMIN. Registration always creates USER; never bound from request bodies.';
COMMENT ON COLUMN users.status IS 'Checked on every authenticated request (JWT validation).';
COMMENT ON COLUMN users.default_location_display IS 'EXACT | DISTRICT | HIDDEN';

-- -----------------------------------------------------------------------------
-- Rotating opaque refresh tokens (SECURITY §5, API /auth/*).
-- Only the SHA-256 hash is stored. A rotated token keeps its row with used_at set,
-- so presenting it again is detectable -> revoke the whole token_family.

CREATE TABLE refresh_tokens (
    id           UUID        NOT NULL,
    user_id      UUID        NOT NULL,
    token_family UUID        NOT NULL,
    token_hash   VARCHAR(64)    NOT NULL,
    issued_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at   TIMESTAMPTZ NOT NULL,
    used_at      TIMESTAMPTZ,
    revoked_at   TIMESTAMPTZ,
    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT uq_refresh_tokens_token_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_tokens_user
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT ck_refresh_tokens_lifetime CHECK (expires_at > issued_at),
    CONSTRAINT ck_refresh_tokens_hash_hex CHECK (token_hash ~ '^[0-9a-f]{64}$')
);

CREATE INDEX idx_refresh_tokens_family  ON refresh_tokens (token_family);
CREATE INDEX idx_refresh_tokens_user_id ON refresh_tokens (user_id);
CREATE INDEX idx_refresh_tokens_expires ON refresh_tokens (expires_at);   -- purge job

COMMENT ON COLUMN refresh_tokens.token_hash IS 'Lower-case hex SHA-256 of the opaque token. The raw token is never stored or logged.';

-- -----------------------------------------------------------------------------
-- Idempotency-Key store (API §2 Idempotency). One row per (user, key).
--   same key + same request_hash  -> replay stored response
--   same key + different hash     -> 422 IDEMPOTENCY_KEY_REUSED
--   same key while IN_PROGRESS    -> 409 REQUEST_IN_PROGRESS

CREATE TABLE idempotency_keys (
    user_id         UUID         NOT NULL,
    idempotency_key VARCHAR(128) NOT NULL,
    request_method  VARCHAR(10)  NOT NULL,
    request_path    VARCHAR(300) NOT NULL,
    request_hash    VARCHAR(64)     NOT NULL,
    status          VARCHAR(16)  NOT NULL DEFAULT 'IN_PROGRESS',
    response_status SMALLINT,
    response_body   JSONB,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ  NOT NULL,
    CONSTRAINT pk_idempotency_keys PRIMARY KEY (user_id, idempotency_key),
    CONSTRAINT fk_idempotency_keys_user
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT ck_idempotency_keys_status CHECK (status IN ('IN_PROGRESS', 'COMPLETED')),
    CONSTRAINT ck_idempotency_keys_completed CHECK (status <> 'COMPLETED' OR response_status IS NOT NULL),
    CONSTRAINT ck_idempotency_keys_expiry CHECK (expires_at > created_at)
);

CREATE INDEX idx_idempotency_keys_expires_at ON idempotency_keys (expires_at);   -- purge job

COMMENT ON COLUMN idempotency_keys.response_body IS 'Stored response for replay. Must not contain presigned URLs or tokens that outlive their own expiry.';

-- -----------------------------------------------------------------------------
-- Audit trail for every /admin/** action (SECURITY TM-4.4). Append-only.

CREATE TABLE admin_audit_logs (
    id            UUID         NOT NULL,
    admin_user_id UUID         NOT NULL,
    action        VARCHAR(80)  NOT NULL,
    target_type   VARCHAR(60)  NOT NULL,
    target_id     UUID,
    details       JSONB,
    occurred_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_admin_audit_logs PRIMARY KEY (id),
    CONSTRAINT fk_admin_audit_logs_user
        FOREIGN KEY (admin_user_id) REFERENCES users (id)   -- RESTRICT: audit rows outlive account cleanup
);

CREATE INDEX idx_admin_audit_logs_admin_occurred ON admin_audit_logs (admin_user_id, occurred_at DESC);
CREATE INDEX idx_admin_audit_logs_target         ON admin_audit_logs (target_type, target_id);

COMMENT ON COLUMN admin_audit_logs.details IS 'Changed fields / outcome. Never raw coordinates, tokens or signed URLs.';

CREATE FUNCTION trg_admin_audit_logs_immutable() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'admin_audit_logs is append-only (% not allowed)', TG_OP;
END;
$$;

CREATE TRIGGER admin_audit_logs_immutable
    BEFORE UPDATE OR DELETE ON admin_audit_logs
    FOR EACH ROW EXECUTE FUNCTION trg_admin_audit_logs_immutable();
